mapper.update:
update room_type
type_name = #{typeName}, price = #{price}, area = #{area}, bed_type = #{bedType}, max_guests = #{maxGuests}, description = #{description}, facilities = #{facilities}, weight = #{weight}, status = #{status}, update_time = SYSDATE
where id = #{id}

mapper.select:
SELECT a.id, a.type_name, a.price, a.area, a.bed_type, a.max_guests, a.description, a.facilities, a.weight, a.status, b.image_url as mainImage FROM room_type a LEFT JOIN (SELECT room_type_id, image_url FROM room_type_image WHERE is_main = 1) b ON a.id = b.room_type_id WHERE a.status = 1
AND a.id = #{roomTypeId}
AND a.price >= #{minPrice}
AND a.price <= #{maxPrice}
AND a.max_guests >= #{maxGuests}
ORDER BY a.weight DESC, a.id ASC
